public static int sumFrom(int[] arr, int i) {
    if (i == arr.length) {
        return 0;
    }
    return arr[i] + sumFrom(arr, i + 1);
}

public static int countFrom(int[] arr, int i, int x) {
    if (i == arr.length) {
        return 0;
    }
    int rest = countFrom(arr, i + 1, x);
    if (arr[i] == x) {
        return rest + 1;
    }
    return rest;
}

exercise.mainCode:
int[] arr = { 2, 7, 3, 7, 2 };
System.out.println("סעיף א: " + sumFrom(arr, 0) + " " + sumFrom(arr, 3));
System.out.println("סעיף ב: " + countFrom(arr, 0, 7) + " " + countFrom(arr, 0, 5));

